#!/usr/bin/env python3
"""Generate journey/ (by stage) and departments/ (by domain) from registry/registry.yaml.

Usage:
    python scripts/build_views.py           # write the views
    python scripts/build_views.py --check   # exit 1 if the committed views are stale
"""
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
REGISTRY = ROOT / "registry" / "registry.yaml"
HEADER = (
    "<!-- GENERATED by scripts/build_views.py from registry/registry.yaml. "
    "Do not edit by hand. -->\n"
)


def load():
    with open(REGISTRY, encoding="utf-8") as f:
        return yaml.safe_load(f)


def link(entry, base):
    """Markdown link from a generated file in `base` (a repo-relative dir) to the entry."""
    prefix = "../" * len(Path(base).parts)
    if entry["kind"] == "external":
        return f"[{entry['id']}](https://github.com/{entry['source']})"
    return f"[{entry['id']}]({prefix}{entry['path']}/)"


def row(entry, base):
    kind = entry["kind"]
    if kind == "external":
        kind = f"external ({entry['mode']}, {entry['license']})"
    return f"| {link(entry, base)} | {kind} | {entry['summary']} |"


def table(entries, base):
    if not entries:
        return "_Nothing registered yet._\n"
    lines = ["| Name | Kind | What it does |", "|---|---|---|"]
    lines += [row(e, base) for e in sorted(entries, key=lambda e: (e["kind"], e["id"]))]
    return "\n".join(lines) + "\n"


def build(reg):
    """Return {relative_path: content} for every generated file."""
    stages, domains, entries = reg["stages"], reg["domains"], reg["entries"]
    out = {}

    # ---- Journey (by stage) ----
    idx = [HEADER, "# Journey: build the company stage by stage\n",
           "Work top to bottom. Each stage ends with an **exit gate**; don't move on until you pass it.\n",
           "| Stage | Purpose | Exit gate |", "|---|---|---|"]
    for s in stages:
        idx.append(f"| [{s['id']} {s['name']}](./{s['id']}.md) | {s['purpose']} | {s['exit_gate']} |")
    idx.append("\nPrefer to browse by function? See [departments](../departments/README.md).\n")
    out["journey/README.md"] = "\n".join(idx)
    for i, s in enumerate(stages):
        here = [e for e in entries if e["stage"] == s["id"]]
        nav = []
        if i > 0:
            nav.append(f"[← {stages[i-1]['id']}](./{stages[i-1]['id']}.md)")
        nav.append("[all stages](./README.md)")
        if i < len(stages) - 1:
            nav.append(f"[{stages[i+1]['id']} →](./{stages[i+1]['id']}.md)")
        body = [HEADER, f"# Stage {s['id']}: {s['name']}\n", " · ".join(nav) + "\n",
                f"**Purpose.** {s['purpose']}\n", f"**Exit gate.** {s['exit_gate']}\n",
                "## Tools for this stage\n", table(here, "journey")]
        out[f"journey/{s['id']}.md"] = "\n".join(body)

    # ---- Departments (by domain) ----
    idx = [HEADER, "# Departments: browse by function\n",
           "Every skill, agent, template and external repo, grouped by the department it serves.\n",
           "| Department | Items |", "|---|---|"]
    for d in domains:
        n = sum(1 for e in entries if d["id"] in e["domains"])
        idx.append(f"| [{d['name']}](./{d['id']}.md) | {n} |")
    idx.append("\nPrefer a step-by-step order? See the [journey](../journey/README.md).\n")
    out["departments/README.md"] = "\n".join(idx)
    for d in domains:
        here = [e for e in entries if d["id"] in e["domains"]]
        sections = []
        for s in stages:
            sub = [e for e in here if e["stage"] == s["id"]]
            if sub:
                sections.append(f"### {s['id']} {s['name']}\n\n{table(sub, 'departments')}")
        body = [HEADER, f"# {d['name']}\n", "[all departments](./README.md)\n"]
        body += sections or ["_Nothing registered yet._\n"]
        out[f"departments/{d['id']}.md"] = "\n".join(body)
    return out


def main():
    check = "--check" in sys.argv
    files = build(load())
    stale = []
    for rel, content in files.items():
        path = ROOT / rel
        if check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                stale.append(rel)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8", newline="\n")
    if check:
        if stale:
            print("Generated views are stale. Run: python scripts/build_views.py")
            for rel in stale:
                print("  -", rel)
            return 1
        print(f"Views up to date ({len(files)} files).")
        return 0
    print(f"Wrote {len(files)} files.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
